const lessons={flow:{title:'Watch a distribution become noise—and back.',copy:'Three colored data populations blur into one Gaussian as noise grows. Move the slider toward data to reveal the peaks. The curve is an exact one-dimensional Gaussian-mixture marginal; reversing this slider is not a learned reverse-diffusion sampler.',source:'https://arxiv.org/abs/2210.02747',label:'Diffusion distributions · from noise to three data modes',caveat:'Distribution mode: xₜ = αxdata + √(1−α²)ε, α = sin(πt/2), with independent standard Gaussian ε. Transport modes are separate hand-defined schematics, not trained models.',options:[['density','Diffusion: distribution'],['flow','Flow: transport'],['diffusion','Diffusion-style path']]},attention:{title:'Every query chooses what to read.',copy:'Attention turns query–key scores into a weighted mixture of values. Causal masking restricts access to the past. This sparse illustration retains top-scoring keys; a real fast implementation must also manage selection overhead and memory traffic.',source:'https://arxiv.org/abs/2609.20888v2',label:'Query × key · toy attention weights',caveat:'Synthetic scores. Top-k sparsity is a teaching device, not an implementation of ETA or a measured speedup. Each visible query row is normalized.',options:[['dense','Dense'],['causal','Causal'],['sparse','Sparse top-k']]},lora:{title:'Context and adaptation do different jobs.',copy:'LoRA represents a weight update as B × A with a small inner rank. IC-LoRA adds task-specific LoRA tuning to a joint image-and-caption setup. At inference, reference images condition generation; they do not automatically update the weights.',source:'https://arxiv.org/abs/2410.23775v3',label:'Low-rank adaptation · shared image context',caveat:'Schematic matrices and image slots. Rank controls the update capacity; it does not predict image quality. IC-LoRA is a 2024 foundation, not a new September 2026 result.',options:[['lora','Low-rank update'],['context','IC-LoRA context']]}};
function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').style.display='none',2300)}
