function draw(){let t=Number($('#progress').value)/100,mode=$('#mode').value;ctx.fillStyle='#ffffff';ctx.fillRect(0,0,1200,650);for(let x=30;x<1200;x+=30)for(let y=25;y<650;y+=30)dot(x,y,1,'#eef1f6');if(topic==='flow'&&mode==='density'){drawDensity(t)}else if(topic==='flow'){label('PRIOR / NOISE',65,57,17);label('DATA / STRUCTURE',1135,57,17,'#5145cd','right');label(mode==='flow'?'CONDITIONAL TRANSPORT SCHEMATIC':'NOISY PATH SCHEMATIC',600,610,15,'#5c6b82','center');for(let i=0;i<250;i++){let a=random(i+1),b=random(i+911),sx=200+(a-.5)*260,sy=325+(b-.5)*360;let angle=random(i+771)*Math.PI*2,rad=32+random(i+212)*75,k=i%3;let ex=900+Math.cos(angle)*rad+(k===0?-65:k===1?65:0),ey=325+Math.sin(angle)*rad+(k-1)*100;let x=sx+(ex-sx)*t,y=sy+(ey-sy)*t;let n=Math.sin(Math.PI*t);if(mode==='diffusion'){x+=Math.sin(i*3+t*23)*55*n;y+=Math.cos(i*7+t*31)*55*n}else{y+=Math.sin(i*.7)*35*n}if(i%5===0){ctx.globalAlpha=.16;line(sx,sy,ex,ey,'#008ba3');ctx.globalAlpha=1}dot(sx,sy,1.5,'#bac6d4');dot(ex,ey,1.5,'#d7d1f0');dot(x,y,2.5+random(i)*1.7,k===0?'#008ba3':k===1?'#5145cd':'#ee875c')}label('t = '+t.toFixed(2),65,610,20,'#18243b');}
else if(topic==='attention'){let n=10,size=43,left=410,top=95,k=1+Math.round(t*9);label('KEY POSITIONS →',625,64,17,'#5c6b82','center');label('QUERY',270,285,17);label('POSITIONS',270,312,17);let active=0;for(let r=0;r<n;r++){let scores=Array.from({length:n},(_,c)=>Math.exp(2*Math.sin(r*1.7+c*.8)+1.4*Math.cos(r-c)));let chosen=scores.map((v,c)=>[v,c]).sort((a,b)=>b[0]-a[0]).slice(0,k).map(x=>x[1]);let vals=scores.map((v,c)=>(mode==='causal'&&c>r)||(mode==='sparse'&&!chosen.includes(c))?0:v);let sum=vals.reduce((a,b)=>a+b,0);for(let c=0;c<n;c++){let v=vals[c]/sum;if(v)active++;ctx.fillStyle=v?`rgba(81,69,205,${.10+.90*Math.sqrt(v)})`:'#edf1f6';ctx.fillRect(left+c*size,top+r*size,size-5,size-5)}label(r+1,left-17,top+r*size+25,14,'#5c6b82','right')}for(let c=0;c<n;c++)label(c+1,left+c*size+18,top+n*size+22,14,'#5c6b82','center');label(mode==='sparse'?`${k} retained keys / query`:`${active} allowed query–key pairs`,625,605,21,'#5145cd','center');$('#value').textContent=mode==='sparse'?k+'/10':'—';}
else{let rank=1+Math.round(t*7);$('#value').textContent='r='+rank;function matrix(x,y,w,h,cols,rows,c){for(let j=0;j<rows;j++)for(let i=0;i<cols;i++){ctx.globalAlpha=.2+.7*random(i+j*cols);ctx.fillStyle=c;ctx.fillRect(x+i*w/cols,y+j*h/rows,w/cols-4,h/rows-4)}ctx.globalAlpha=1}if(mode==='lora'){matrix(100,200,220,220,8,8,'#008ba3');label('ΔW',210,170,28,'#18243b','center');label('=',385,327,36,'#5c6b82');matrix(460,200,rank*24,220,rank,8,'#5145cd');label('B',460+rank*12,170,28,'#18243b','center');label('×',730,327,36);matrix(820,200,220,rank*24,8,rank,'#ee875c');label('A',930,170,28,'#18243b','center');label(`8 × 8 update   ·   rank ${rank}   ·   ${16*rank} adapter parameters`,600,520,22,'#5145cd','center');label('Parameter savings only when r(din + dout) < din × dout',600,570,18,'#5c6b82','center')}else{let names=['Reference A','Reference B','Target slot'];for(let i=0;i<3;i++){let x=145+i*320;ctx.strokeStyle=i===2?'#5145cd':'#008ba3';ctx.lineWidth=2;ctx.strokeRect(x,155,250,190);label(names[i],x+125,263,23,'#18243b','center');if(i<2)line(x+253,250,x+315,250,'#5c6b82',2)}label('JOINT IMAGE CANVAS + JOINT CAPTION',600,405,21,'#5145cd','center');label('Shared DiT computation · task-specific LoRA weights',600,460,21,'#18243b','center');label('Conditioning at inference ≠ updating weights',600,550,20,'#5c6b82','center')}}}
function drawDensity(t){
 if(canvas.clientWidth<600){drawCompactDensity(t);return}
 const alpha=Math.sin(t*Math.PI/2),variance=alpha*alpha*.16+(1-alpha*alpha),sd=Math.sqrt(variance),means=[-2.5,0,2.5],colors=['#008ba3','#5145cd','#df7850'];
 const px=x=>100+(x+5)*100,py=y=>470-y*620;
 label('PROBABILITY DENSITY',100,60,17,'#5c6b82');label(t<.02?'STANDARD GAUSSIAN NOISE':t>.98?'THREE DATA POPULATIONS':'PARTIALLY NOISED DATA',1100,60,17,'#5145cd','right');
 for(let k=0;k<=3;k++){let y=k*.2;line(100,py(y),1100,py(y),'#e7ecf3');label(y.toFixed(1),82,py(y)+5,15,'#5c6b82','right')}
 line(100,470,1100,470,'#c5cfdf',2);for(let x=-4;x<=4;x+=2){label(String(x),px(x),498,17,'#5c6b82','center')}label('x  /  toy feature value',600,530,17,'#5c6b82','center');
 const normal=(x,m,s)=>Math.exp(-.5*((x-m)/s)**2)/(s*Math.sqrt(2*Math.PI));
 for(let k=0;k<3;k++){ctx.beginPath();ctx.moveTo(100,470);for(let i=0;i<=400;i++){let x=-5+i/40;ctx.lineTo(px(x),py(normal(x,alpha*means[k],sd)/3))}ctx.lineTo(1100,470);ctx.closePath();ctx.fillStyle=colors[k]+'24';ctx.fill();ctx.beginPath();for(let i=0;i<=400;i++){let x=-5+i/40,y=normal(x,alpha*means[k],sd)/3;i?ctx.lineTo(px(x),py(y)):ctx.moveTo(px(x),py(y))}ctx.strokeStyle=colors[k];ctx.lineWidth=2.5;ctx.stroke()}
 ctx.beginPath();for(let i=0;i<=400;i++){let x=-5+i/40,y=means.reduce((v,m)=>v+normal(x,alpha*m,sd)/3,0);i?ctx.lineTo(px(x),py(y)):ctx.moveTo(px(x),py(y))}ctx.strokeStyle='#18243b';ctx.lineWidth=3;ctx.stroke();
 for(let i=0;i<150;i++){let z=Math.sqrt(-2*Math.log(Math.max(.001,random(i+310))))*Math.cos(2*Math.PI*random(i+911));let e=Math.sqrt(-2*Math.log(Math.max(.001,random(i+710))))*Math.cos(2*Math.PI*random(i+1811));let x=alpha*(means[i%3]+.4*z)+Math.sqrt(1-alpha*alpha)*e;if(x>=-5&&x<=5)dot(px(x),565+random(i+80)*24,3,colors[i%3])}
 label('● Population A',110,630,16,colors[0]);label('● Population B',350,630,16,colors[1]);label('● Population C',590,630,16,colors[2]);label('— Total density',1100,630,16,'#18243b','right');
}
function drawCompactDensity(t){
 const a=Math.sin(t*Math.PI/2),sd=Math.sqrt(a*a*.16+1-a*a),means=[-2.5,0,2.5],colors=['#008ba3','#5145cd','#df7850'];
 const px=x=>140+(x+5)*94,py=y=>455-y*720,normal=(x,m)=>Math.exp(-.5*((x-m)/sd)**2)/(sd*Math.sqrt(2*Math.PI));
 label('Density',140,68,46,'#18243b');label(t<.02?'Noise':t>.98?'Data':'Noise → data',1080,68,46,'#5145cd','right');
 for(let y of [0,.2,.4]){line(140,py(y),1080,py(y),'#e0e6ef',2);label(y.toFixed(1),110,py(y)+15,40,'#5c6b82','right')}
 for(let k=0;k<3;k++){ctx.beginPath();ctx.moveTo(140,455);for(let i=0;i<=250;i++){let x=-5+i/25;ctx.lineTo(px(x),py(normal(x,a*means[k])/3))}ctx.lineTo(1080,455);ctx.closePath();ctx.fillStyle=colors[k]+'25';ctx.fill();ctx.beginPath();for(let i=0;i<=250;i++){let x=-5+i/25;i?ctx.lineTo(px(x),py(normal(x,a*means[k])/3)):ctx.moveTo(px(x),py(normal(x,a*means[k])/3))}ctx.strokeStyle=colors[k];ctx.lineWidth=5;ctx.stroke()}
 ctx.beginPath();for(let i=0;i<=250;i++){let x=-5+i/25,y=means.reduce((v,m)=>v+normal(x,a*m)/3,0);i?ctx.lineTo(px(x),py(y)):ctx.moveTo(px(x),py(y))}ctx.strokeStyle='#18243b';ctx.lineWidth=6;ctx.stroke();
 for(let x of [-4,0,4])label(String(x),px(x),510,43,'#5c6b82','center');label('Toy feature value',600,567,43,'#5c6b82','center');
 label('● A',160,630,44,colors[0]);label('● B',385,630,44,colors[1]);label('● C',610,630,44,colors[2]);label('— Sum',1080,630,44,'#18243b','right');
}
function setTopic(v){topic=v;playing=false;$('#play').textContent='▶ Play';let l=lessons[v];$('#mode').innerHTML=l.options.map(([v,t])=>`<option value="${v}">${t}</option>`).join('');$('#lesson-title').textContent=l.title;$('#lesson-copy').textContent=l.copy;$('#lesson-source').href=l.source;$('#lesson-source').textContent=v==='attention'?'Recent connection: ETA v2 ↗':'Foundational reading ↗';$('#visual-label').textContent=l.label;$('#visual-caveat').textContent=l.caveat;$('#slider-name').textContent=v==='flow'?'Generation progress':v==='attention'?'Keys retained (sparse)':'Adapter rank';$$('.lesson').forEach(b=>b.classList.toggle('active',b.dataset.topic===v));$('#step-number').textContent='0'+(Object.keys(lessons).indexOf(v)+1);update()}
function update(){
 $('#value').textContent=$('#progress').value+'%';
 if(topic==='flow'){
  const mode=$('#mode').value,l=lessons.flow;
  $('#lesson-title').textContent=mode==='density'?l.title:'Follow a path from noise toward structure.';
  $('#lesson-copy').textContent=mode==='density'?l.copy:'This hand-defined particle transport illustrates a change from a simple cloud toward structured populations. Flow matching learns a velocity field; this sketch does not. The noisy-path option is a visual analogy, not a diffusion solver.';
  $('#lesson-source').href=mode==='density'?'https://arxiv.org/abs/2011.13456':'https://arxiv.org/abs/2210.02747';
  $('#visual-caveat').textContent=mode==='density'?l.caveat:'Hand-defined endpoints and paths. Neither a trained flow field nor a DDPM solver. Real diffusion models can also use deterministic samplers; this is not a method-quality comparison.';
  $('#visual-label').textContent=mode==='density'?l.label:'Noise-to-structure transport · illustrative paths';
 }
 draw()
}
$$('.lesson').forEach(b=>b.onclick=()=>setTopic(b.dataset.topic));$('#progress').oninput=update;$('#mode').onchange=update;
$('#play').onclick=()=>{if(topic!=='flow'){toast('Animation is available in Noise → structure.');return}playing=!playing;$('#play').textContent=playing?'Ⅱ Pause':'▶ Play'};
function animate(time){if(playing&&time-frame>45){frame=time;$('#progress').value=(Number($('#progress').value)+1)%101;update()}requestAnimationFrame(animate)}requestAnimationFrame(animate);
function saveBlob(blob,name){let a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
$('#export').onclick=()=>{let out=document.createElement('canvas');out.width=1200;out.height=760;let c=out.getContext('2d');c.fillStyle='#ffffff';c.fillRect(0,0,1200,760);c.drawImage(canvas,0,0);c.fillStyle='#5145cd';c.font='20px sans-serif';c.fillText('FRONTIER FIELDNOTES / KAVEH',35,690);c.fillStyle='#5c6b82';c.font='17px sans-serif';c.fillText('Educational schematic · not model output or benchmark evidence',35,730);out.toBlob(b=>saveBlob(b,`fieldnotes-${topic}.png`))};
function showSlide(){let settings=[['flow','density',0],['flow','density',40],['flow','density',75],['flow','density',100]][slide];setTopic(settings[0]);$('#mode').value=settings[1];$('#progress').value=settings[2];update();$('#slide-status').textContent=`${slide+1} / 4`;$('#prev-slide').disabled=slide===0;$('#next-slide').disabled=slide===3}
$('#present').onclick=()=>{document.body.classList.add('presenting');slide=0;showSlide();window.scrollTo(0,0)};$('#exit-present').onclick=()=>document.body.classList.remove('presenting');$('#prev-slide').onclick=()=>{slide=Math.max(0,slide-1);showSlide()};$('#next-slide').onclick=()=>{slide=Math.min(3,slide+1);showSlide()};document.addEventListener('keydown',e=>{if(!document.body.classList.contains('presenting')||/INPUT|SELECT|TEXTAREA/.test(e.target.tagName))return;if(e.key==='Escape')$('#exit-present').click();if(e.key==='ArrowRight')$('#next-slide').click();if(e.key==='ArrowLeft')$('#prev-slide').click()});
function renderPapers(filter='all'){$('#papers').replaceChildren();PAPERS.filter(p=>filter==='all'||p.category===filter).forEach(p=>{let a=document.createElement('article');a.className='paper';let meta=document.createElement('div');meta.className='meta';let cat=document.createElement('span');cat.textContent=p.category;let date=document.createElement('span');date.textContent=p.date+' · '+p.version;meta.append(cat,date);a.append(meta);for(let [tag,txt,cls] of [['h3',p.title],['p',p.summary],['p',p.caveat,'caution']]){let e=document.createElement(tag);e.textContent=txt;if(cls)e.className=cls;a.append(e)}if(p.change){const note=document.createElement('p');note.textContent=p.change;note.className='caution';a.append(note)}if(p.evaluation){const details=document.createElement('details');const summary=document.createElement('summary');summary.textContent='Evaluation, access & creator use';details.append(summary);for(const label of ['evaluation','access','creator_implication']){const line=document.createElement('p');line.textContent=p[label];details.append(line)}a.append(details)}let link=document.createElement('a');link.href=p.url;link.textContent='Read primary source ↗';a.append(link);$('#papers').append(a)})}
